# Limit what domains can mount filesystems or change their mount flags.
# sdcard_type (including vfat and exfat) and fusefs_type are exempt as a larger
# set of domains need this capability, including device-specific domains.
neverallow {
    domain
    -apexd
# These types must exist when platform policy is compiled, before system_ext.
# The optional NNS storage integration supplies their service permissions.
type nns_storage, domain, coredomain;
type nns_storage_file, file_type, data_file_type, core_data_file_type;

# Limit what domains can mount filesystems or change their mount flags.
# sdcard_type (including vfat and exfat) and fusefs_type are exempt as a larger
# set of domains need this capability, including device-specific domains.
neverallow {
    domain
    -nns_storage
    -apexd
    -fusefs_type
}:filesystem { mount remount relabelfrom relabelto };
    -fusefs_type
}:filesystem { mount remount relabelfrom relabelto };

# NNS can create labeled mounts, but cannot change or remove existing mounts.
neverallow nns_storage fs_type:filesystem { remount unmount relabelfrom relabelto };
neverallow nns_storage { fs_type -labeledfs }:filesystem mount;

# Only vold should ever add/remove file-based encryption keys.
neverallowxperm {
  domain
  -vold
} data_file_type:dir ioctl { FS_IOC_ADD_ENCRYPTION_KEY FS_IOC_REMOVE_ENCRYPTION_KEY FS_IOC_GET_ENCRYPTION_KEY_STATUS };

# Only vold should ever add/remove file-based encryption keys.
neverallowxperm {
  domain
  -vold
} data_file_type:dir ioctl { FS_IOC_ADD_ENCRYPTION_KEY FS_IOC_REMOVE_ENCRYPTION_KEY };

# NNS can query key status through its private configuration directory only.
neverallowxperm {
  domain
  -vold
  -nns_storage
} data_file_type:dir ioctl { FS_IOC_GET_ENCRYPTION_KEY_STATUS };
neverallowxperm nns_storage { data_file_type -nns_storage_file }:dir ioctl { FS_IOC_GET_ENCRYPTION_KEY_STATUS };
# Also forbid the separate remove-for-all-users ioctl for NNS.
neverallowxperm nns_storage data_file_type:dir ioctl { 0x6619 };
